#!/usr/bin/env python3
"""Add each docs page's last-edit date to a docs config (extra.page_dates).

    docs_page_dates.py <mkdocs.yaml>                    edit the config in place (CI worktree)
    docs_page_dates.py <mkdocs.yaml> --out <child.yaml>  write a child config that INHERITs it (local preview)

The date of a page is the date of the last commit that changed its source file;
a file with uncommitted changes, or one not tracked yet, gets its modification
date instead. Keys are page URLs without slashes (doc_parameters, CHANGELOG; the
home page is ""), the form overrides/partials/copyright.html looks them up in.
Dates read "18 November 2026". Plain text edits, because the config may hold
tags (!!python/name) that a YAML loader rejects.
"""

import datetime as dt
import os
import re
import subprocess
import sys


def page_key(rel: str) -> str:
    """Page URL key of a docs source path (directory URLs, README/index = section root)."""
    stem = rel[:-3] if rel.endswith(".md") else rel
    parts = stem.split("/")
    if parts[-1] in ("README", "index"):
        parts = parts[:-1]
    return "/".join(parts)


def fmt(day: dt.date) -> str:
    return f"{day.day} {day:%B %Y}"


def page_dates(root: str, docs_dir: str) -> dict:
    def git(*args):
        return subprocess.run(["git", "-C", root, *args], check=True,
                              capture_output=True, text=True).stdout

    dates = {}
    day = None
    # One pass over the history: the first date seen for a file is its last commit.
    for line in git("log", "--format=@%cs", "--name-only", "--", docs_dir).splitlines():
        if line.startswith("@"):
            day = dt.date.fromisoformat(line[1:])
        elif line.endswith(".md") and line.startswith(docs_dir + "/"):
            dates.setdefault(line[len(docs_dir) + 1:], day)
    # Uncommitted or untracked files: modification date.
    for line in git("status", "--porcelain", "--untracked-files=all", "--", docs_dir).splitlines():
        path = line[3:].split(" -> ")[-1].strip('"')
        if path.endswith(".md") and os.path.exists(os.path.join(root, path)):
            mtime = os.path.getmtime(os.path.join(root, path))
            dates[path[len(docs_dir) + 1:]] = dt.date.fromtimestamp(mtime)
    # Only pages that still exist.
    return {page_key(rel): fmt(day) for rel, day in sorted(dates.items())
            if os.path.exists(os.path.join(root, docs_dir, rel))}


def yaml_block(dates: dict, indent: str) -> str:
    lines = [f"{indent}page_dates:"]
    lines += [f"{indent}  '{key}': '{value}'" for key, value in dates.items()]
    return "\n".join(lines)


if __name__ == "__main__":
    cfg = sys.argv[1]
    out = sys.argv[sys.argv.index("--out") + 1] if "--out" in sys.argv else None
    root = os.path.dirname(os.path.abspath(cfg))
    with open(cfg) as f:
        text = f.read()
    m = re.search(r"(?m)^docs_dir:\s*['\"]?([^'\"\s#]+)", text)
    docs_dir = (m.group(1) if m else "docs").rstrip("/")
    dates = page_dates(root, docs_dir)
    if out:
        with open(out, "w") as f:
            f.write(f"# Generated by .github/scripts/docs_page_dates.py: {os.path.basename(cfg)} + page dates.\n"
                    f"INHERIT: {os.path.relpath(cfg, os.path.dirname(os.path.abspath(out)))}\n\n"
                    f"extra:\n{yaml_block(dates, '  ')}\n")
    else:
        block = yaml_block(dates, "  ")
        if re.search(r"(?m)^extra:\s*$", text):
            text = re.sub(r"(?m)^extra:\s*$", lambda _: "extra:\n" + block, text, count=1)
        else:
            text = text.rstrip("\n") + "\n\nextra:\n" + block + "\n"
        with open(cfg, "w") as f:
            f.write(text)
    print(f"page dates for {len(dates)} pages", file=sys.stderr)
